def sign_out(self, username: str) -> None:
    # Invalidate refresh tokens
    for token, token_tuple in list(self.refresh_tokens.items()):
        if token_tuple is None:
            continue
        _, logged_in_user, _ = token_tuple
        if username == logged_in_user:
            self.refresh_tokens[token] = None

    # Invalidate access tokens
    for token, token_tuple in list(self.access_tokens.items()):
        _, logged_in_user = token_tuple
        if username == logged_in_user:
            del self.access_tokens[token]

    # Invalidate id tokens
    for token, token_tuple in list(self.id_tokens.items()):
        _, logged_in_user = token_tuple
        if username == logged_in_user:
            del self.id_tokens[token]
